      "keystrokes": "pdftotext input_notes.pdf - 2>/dev/null || python3 -c \"\nimport subprocess\nresult = subprocess.run(['pdftotext', 'input_notes.pdf', '-'], capture_output=True, text=True)\nprint(result.stdout)\n\"\n",
